/* Convertible — static site stylesheet */
/* Zero external dependencies, just like the project */

/* ── Reset & Base ───────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg:       #0b0f19;
  --clr-surface:  #131926;
  --clr-border:   #1e2737;
  --clr-text:     #c9d1d9;
  --clr-heading:  #e6edf3;
  --clr-accent:   #58a6ff;
  --clr-accent2:  #3fb950;
  --clr-muted:    #8b949e;
  --clr-tag:      #1c2333;
  --clr-tag-text: #79c0ff;
  --max-w:        1080px;
  --radius:       10px;
  --font-mono:    "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  --font-sans:    -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--clr-accent); text-decoration: none; }
a:hover { text-decoration: underline; }

img, svg { display: block; max-width: 100%; }

/* ── Utility ────────────────────────────────────────── */
.container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

/* ── Skip link ──────────────────────────────────────── */
.skip-link {
  position: absolute; top: -100%; left: 16px;
  background: var(--clr-accent); color: #000;
  padding: 6px 14px; border-radius: 6px; font-weight: 600;
  z-index: 100;
}
.skip-link:focus { top: 12px; }

/* ── Header / Nav ───────────────────────────────────── */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(11,15,25,.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--clr-border);
}
.nav-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-w); margin: 0 auto; padding: 0 24px; height: 56px;
}
.nav-brand {
  font-weight: 700; font-size: 1.15rem; color: var(--clr-heading);
  display: flex; align-items: center; gap: 8px;
}
.nav-brand .dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--clr-accent); display: inline-block;
}
.nav-links { display: flex; gap: 24px; list-style: none; }
.nav-links a {
  color: var(--clr-muted); font-size: .9rem; font-weight: 500;
  transition: color .2s;
}
.nav-links a:hover { color: var(--clr-heading); text-decoration: none; }

/* ── Hero ───────────────────────────────────────────── */
.hero {
  padding: 100px 24px 80px;
  text-align: center;
  background:
    radial-gradient(ellipse 60% 50% at 50% 0%, rgba(88,166,255,.08) 0%, transparent 100%),
    var(--clr-bg);
}
.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  font-weight: 800;
  color: var(--clr-heading);
  line-height: 1.15;
  margin-bottom: 20px;
}
.hero h1 .accent { color: var(--clr-accent); }
.hero .tagline {
  font-size: clamp(1.05rem, 2.2vw, 1.35rem);
  color: var(--clr-muted);
  max-width: 640px;
  margin: 0 auto 36px;
}
.hero-actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 12px 26px; border-radius: 8px; font-weight: 600;
  font-size: .95rem; border: none; cursor: pointer;
  transition: background .2s, transform .15s;
}
.btn:hover { transform: translateY(-1px); text-decoration: none; }
.btn-primary { background: var(--clr-accent); color: #000; }
.btn-primary:hover { background: #79c0ff; }
.btn-secondary { background: var(--clr-surface); color: var(--clr-heading); border: 1px solid var(--clr-border); }
.btn-secondary:hover { border-color: var(--clr-accent); }

/* ── ASCII banner ───────────────────────────────────── */
.ascii-banner {
  margin: 48px auto 0;
  max-width: 720px;
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius);
  padding: 20px 24px;
  text-align: left;
  overflow-x: auto;
}
.ascii-banner pre {
  font-family: var(--font-mono);
  font-size: .65rem;
  line-height: 1.25;
  color: var(--clr-accent);
  white-space: pre;
}

/* ── Section shared ─────────────────────────────────── */
.section {
  padding: 80px 24px;
}
.section-heading {
  text-align: center;
  margin-bottom: 56px;
}
.section-heading h2 {
  font-size: clamp(1.6rem, 3.5vw, 2.4rem);
  font-weight: 700;
  color: var(--clr-heading);
  margin-bottom: 12px;
}
.section-heading p {
  color: var(--clr-muted);
  max-width: 560px;
  margin: 0 auto;
  font-size: 1.05rem;
}

/* ── Metaphor table ─────────────────────────────────── */
.metaphor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
  max-width: var(--max-w);
  margin: 0 auto;
}
.metaphor-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius);
  padding: 22px 24px;
  transition: border-color .2s;
}
.metaphor-card:hover { border-color: var(--clr-accent); }
.metaphor-card .part {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--clr-tag-text);
  background: var(--clr-tag);
  padding: 3px 10px;
  border-radius: 6px;
  margin-bottom: 10px;
}
.metaphor-card h3 {
  font-size: 1.05rem;
  color: var(--clr-heading);
  margin-bottom: 6px;
}
.metaphor-card p {
  font-size: .92rem;
  color: var(--clr-muted);
  line-height: 1.55;
}

/* ── Features ───────────────────────────────────────── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 20px;
  max-width: var(--max-w);
  margin: 0 auto;
}
.feature-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius);
  padding: 28px 26px;
  transition: border-color .2s, transform .15s;
}
.feature-card:hover {
  border-color: var(--clr-accent);
  transform: translateY(-2px);
}
.feature-card .icon {
  width: 40px; height: 40px;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.2rem;
  margin-bottom: 16px;
  background: var(--clr-tag);
  color: var(--clr-accent);
}
.feature-card h3 {
  font-size: 1.05rem;
  color: var(--clr-heading);
  margin-bottom: 8px;
}
.feature-card p {
  font-size: .9rem;
  color: var(--clr-muted);
  line-height: 1.55;
}
.feature-card code {
  font-family: var(--font-mono);
  font-size: .82em;
  background: var(--clr-tag);
  padding: 1px 6px;
  border-radius: 4px;
  color: var(--clr-accent2);
}

/* ── Code block ─────────────────────────────────────── */
.code-block {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius);
  padding: 20px 24px;
  margin: 32px auto 0;
  max-width: 640px;
  overflow-x: auto;
}
.code-block pre {
  font-family: var(--font-mono);
  font-size: .85rem;
  line-height: 1.6;
  color: var(--clr-accent2);
}
.code-block .comment { color: var(--clr-muted); }

/* ── All-engines rule callout ───────────────────────── */
.callout {
  max-width: var(--max-w);
  margin: 48px auto 0;
  background: var(--clr-surface);
  border-left: 4px solid var(--clr-accent);
  border-radius: var(--radius);
  padding: 24px 28px;
}
.callout h3 {
  font-size: 1rem;
  color: var(--clr-heading);
  margin-bottom: 8px;
}
.callout p {
  font-size: .92rem;
  color: var(--clr-muted);
  line-height: 1.6;
}

/* ── Footer ─────────────────────────────────────────── */
.site-footer {
  border-top: 1px solid var(--clr-border);
  padding: 40px 24px;
  text-align: center;
  color: var(--clr-muted);
  font-size: .85rem;
}
.site-footer a { color: var(--clr-accent); }

/* ── Responsive ─────────────────────────────────────── */
@media (max-width: 600px) {
  .nav-links { gap: 16px; }
  .hero { padding: 64px 16px 48px; }
  .section { padding: 48px 16px; }
  .metaphor-grid,
  .features-grid { grid-template-columns: 1fr; }
  .ascii-banner pre { font-size: .5rem; }
}
